What will this Observer design pattern implementation print?

interface Observer {
    void update(int value);
}
class Subject {
    private Observer observer;
    private int state;
    public void attach(Observer obs) { observer = obs; }
    public void setState(int newState) {
        state = newState;
        if (observer != null) observer.update(state);
    }
}
class Display implements Observer {
    public void update(int value) { System.out.print("Value: " + value); }
}

Subject subject = new Subject();
Display display = new Display();
subject.attach(display);
subject.setState(42);

